<script setup>
import {ref,onMounted} from 'vue'
import {api,getSession,setSession,clearSession} from '../../services/api'
import {useRouter} from 'vue-router'
import Navbar from '../../components/admin/Navbar.vue'
import Sidebar from '../../components/admin/Sidebar.vue'
import '../../styles/admin/dashboard.css'
const router=useRouter(),perfil=ref({}),actual=ref(''),nueva=ref(''),confirmar=ref(''),usuario=ref(''),error=ref(''),cargando=ref(false)
const obligatorio=getSession()?.user?.debeCambiarClave
onMounted(async()=>{try{perfil.value=await api('/cuenta/perfil');usuario.value=perfil.value.usuario}catch(e){error.value=e.message}})
async function guardar(){error.value='';if(nueva.value!==confirmar.value){error.value='Las contraseñas no coinciden';return}cargando.value=true;try{await api('/cuenta/credenciales',{method:'PUT',body:JSON.stringify({actual:actual.value,nueva:nueva.value,usuario:usuario.value})});clearSession();router.replace('/login');alert('Credenciales actualizadas. Inicia sesión con tu usuario y contraseña nuevos.')}catch(e){error.value=e.message}finally{cargando.value=false}}
</script>
<template><Navbar/><div class="gato-app-layout"><Sidebar/><main class="gato-content p-4"><h1 class="h3">Mi perfil · Credenciales</h1><p v-if="obligatorio" class="alert alert-warning">Es tu primer ingreso o tu contraseña fue restablecida. Debes configurar una contraseña personal antes de continuar.</p><p>Por seguridad debes ingresar tu contraseña actual (o temporal). El usuario solo puede personalizarse una vez.</p><div class="card p-3" style="max-width:580px"><form @submit.prevent="guardar"><label class="form-label">Nombre de usuario</label><input v-model.trim="usuario" class="form-control mb-2" :disabled="perfil.usuarioPersonalizado||perfil.usuario_personalizado" minlength="4" maxlength="30" required><small class="text-muted">Entre 4 y 30 caracteres; sin espacios.</small><label class="form-label mt-3">Contraseña actual o temporal</label><input v-model="actual" type="password" autocomplete="current-password" class="form-control" required><label class="form-label mt-3">Contraseña personal nueva</label><input v-model="nueva" type="password" autocomplete="new-password" minlength="12" maxlength="128" class="form-control" required><small class="text-muted">Mínimo 12 caracteres. Puede ser una frase larga fácil de recordar.</small><label class="form-label mt-3">Repetir contraseña nueva</label><input v-model="confirmar" type="password" minlength="12" maxlength="128" autocomplete="new-password" required class="form-control mb-3"><div v-if="error" class="alert alert-danger">{{error}}</div><button class="btn btn-primary" :disabled="cargando">Guardar y volver a ingresar</button></form></div></main></div></template>
<style scoped>.gato-app-layout{display:flex;background:#f4f8ff;min-height:calc(100vh - 82px)}.gato-app-layout .gato-content{flex:1}.gato-app-layout :deep(.sidebar){flex:0 0 250px}@media(max-width:760px){.gato-app-layout{flex-direction:column}}</style>
